{
  "technical_and_design_decisions": [
    "Use Spring Boot Security starter (spring-boot-starter-security) for Basic Auth functionality",
    "Control Basic Auth via Spring Boot property server.basic.enabled with default false in application.yml",
    "Single-user security configurations will be provided through a servers.yml file",
    "XD Shell admin config command extended with --username and --password command-line options",
    "Dependency updates (U4, U5) will be done by modifying Maven pom.xml or Gradle build file",
    "Docker images built on Ubuntu base OS, using Java 7, with full XD JAR (and optionally Redis and RabbitMQ for sandbox)",
    "Spike (U6) will produce documentation and new user stories, no implementation code"
  ],
  "assumptions": [
    "Existing Spring XD project source code is available with Maven build system",
    "Developer is experienced with Spring Boot, Spring Security, and Docker",
    "The Spring Boot snapshot and release dependencies are accessible via public repositories",
    "Java 7 is still available and compatible with the XD jar and other components",
    "Docker environment is available for building and testing images",
    "The spike (U6) is a research-only activity, not involving code implementation",
    "All testing (unit, integration) is included within each activity's effort estimate"
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Add Basic Auth support",
      "activity_description": "Add spring-boot-starter-security dependency to spring-xd-dirt project; configure server.basic.enabled property with default false in application.yml; verify functionality.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2",
      "activity_name": "Single-user security configurations",
      "activity_description": "Implement reading and applying single-user security credentials (username/password) from a servers.yml file; integrate with existing security configuration.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Add username/password to admin config command",
      "activity_description": "Extend the XD Shell admin config command to accept --username and --password options; store and use credentials for Basic Auth with admin server.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Update to latest Spring Boot snapshot",
      "activity_description": "Update Spring Boot dependency version to the latest snapshot; resolve any compilation or API changes; run existing tests.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5",
      "activity_name": "Update to latest Spring Boot RELEASE",
      "activity_description": "Update Spring Boot dependency version to the latest stable release; verify compatibility and run tests.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6",
      "activity_name": "Spike for REST API push archive",
      "activity_description": "Assess customer requirement, brainstorm and document options, socialize with team for feedback, identify phases, and create new stories for future implementation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Create sandbox Docker image",
      "activity_description": "Create Dockerfile based on Ubuntu OS with Java 7, full XD JAR, Redis, and RabbitMQ; build and test the image; document usage.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Create production-ready Docker image",
      "activity_description": "Create Dockerfile based on Ubuntu OS with Java 7 and full XD JAR (no extra services); build and test the image; document usage.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 15
  }
}

